        table: sourceTable.table,
        source_rows: sourceTable.rows.length,
        target_rows: targetTable?.rows.length ?? 0,
        inserted: 0,
        updated: 0,
        deleted: 0,
        skipped: 0,
        conflicts: 0,
        stale_skipped: 0
