  const maxItems = Math.max(1, Math.min(options.maxItems ?? DEFAULT_MAX_ITEMS2, 1000));
  const evidenceLimit = Math.max(1, Math.min(options.limit ?? DEFAULT_EVIDENCE_LIMIT, 100));
